// @ts-check
const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const path = require('node:path');
const { createServer } = require('./workbench-preview-scroll-fixture.cjs');

let fixture;
let baseUrl;

async function focusByKeyboard(page, target) {
    const tabStops = await page.locator('a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), '
        + 'select:not([disabled]), textarea:not([disabled]), summary, [tabindex]:not([tabindex="-1"])').count();
    for (let index = 0; index < tabStops; index++) {
        await page.keyboard.press('Tab');
        if (await target.evaluate(element => document.activeElement === element)) {
            return;
        }
    }
    throw new Error('The preview scroll region was not reachable through keyboard tab navigation.');
}

test.beforeAll(async () => {
    fixture = createServer();
    await new Promise((resolve, reject) => {
        fixture.once('error', reject);
        fixture.listen(0, '127.0.0.1', resolve);
    });
    const address = fixture.address();
    if (!address || typeof address === 'string') {
        throw new Error('The preview fixture did not bind a TCP port.');
    }
    baseUrl = `http://127.0.0.1:${address.port}`;
});

test.afterAll(async () => {
    if (fixture && fixture.listening) {
        await new Promise((resolve, reject) => fixture.close(error => error ? reject(error) : resolve()));
    }
});

/** Opens the Export or Remove preview of the fixture's statement (or its short one) and waits for its rows. */
async function openPreview(page, viewId, short) {
    if (viewId === 'export') {
        await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/export${short ? '?fixture-preview=short' : ''}`,
            { waitUntil: 'networkidle' });
    } else {
        await page.goto(`${baseUrl}/rdf4j-workbench/repositories/a/remove`, { waitUntil: 'networkidle' });
        const form = page.locator('#remove-form');
        await form.locator('#subj').fill(short ? '<urn:s>' : '<urn:subject:' + 's'.repeat(180) + '>');
        await expect(form.locator('#remove-count')).toHaveText('1 statement matches');
        await form.locator('#remove-preview-button').click();
    }
    const section = viewId === 'export' ? '#export-results' : '#remove-preview';
    // The previews are the Query page's shared result table (.agent/execplans/workbench-shared-result-table.md).
    await expect(page.locator(`${section} .query-result-layout [data-workbench-row-index]`)).toHaveCount(1);
    return section;
}

// The shared result table wraps long values in readable columns, and shows records where four columns do not fit.
test('export and remove previews keep wide RDF statements inside the page', async ({ page }) => {
    const evidenceDirectory = process.env.WORKBENCH_PREVIEW_EVIDENCE;
    if (evidenceDirectory) {
        fs.mkdirSync(evidenceDirectory, { recursive: true });
    }

    for (const [viewId, width] of [['export', 1280], ['export', 390], ['remove', 1280], ['remove', 390]]) {
        await page.setViewportSize({ width, height: 820 });
        const section = await openPreview(page, viewId, false);
        const metrics = await page.locator(`${section} .query-result-layout`).evaluate(layout => {
            const card = layout.closest('section');
            const records = layout.getAttribute('data-effective-layout') === 'records';
            const box = layout.querySelector(records ? ':scope > .query-result-records' : ':scope > .query-result-table-wrap');
            const values = Array.from(box.querySelectorAll(records ? 'dd' : 'tbody td'));
            const graph = values[values.length - 1];
            const subject = values[0].querySelector('a');
            return {
                layout: layout.getAttribute('data-effective-layout'),
                tabindex: box.getAttribute('tabindex'),
                viewportWidth: document.documentElement.clientWidth,
                documentWidth: document.documentElement.scrollWidth,
                cardRight: card.getBoundingClientRect().right,
                boxRight: box.getBoundingClientRect().right,
                boxScrolls: box.scrollWidth > box.clientWidth + 1,
                graphRight: graph.getBoundingClientRect().right,
                graphText: graph.textContent,
                subjectRight: subject.getBoundingClientRect().right,
                subjectCellRight: values[0].getBoundingClientRect().right,
                subjectBreaks: subject.querySelectorAll('wbr').length
            };
        });
        console.log(`PREVIEW_FIT ${viewId} ${width}px ${JSON.stringify(metrics)}`);
        expect.soft(metrics.documentWidth, `${viewId} ${width}px preview does not widen the document`)
            .toBeLessThanOrEqual(metrics.viewportWidth + 1);
        expect.soft(metrics.boxRight, `${viewId} ${width}px preview stays inside its card`)
            .toBeLessThanOrEqual(metrics.cardRight + 1);
        expect.soft(metrics.boxScrolls, `${viewId} ${width}px long values wrap instead of widening the preview`).toBe(false);
        expect.soft(metrics.graphRight, `${viewId} ${width}px the Graph value is visible`)
            .toBeLessThanOrEqual(metrics.boxRight + 1);
        expect.soft(metrics.graphText, `${viewId} ${width}px preserves the final graph value`).toContain('urn:graph:');
        expect.soft(metrics.subjectBreaks, `${viewId} ${width}px the IRI may break after its colons`).toBeGreaterThan(0);
        expect.soft(metrics.subjectRight, `${viewId} ${width}px the long IRI stays in its cell`)
            .toBeLessThanOrEqual(metrics.subjectCellRight + 1);
        expect.soft(metrics.tabindex, `${viewId} ${width}px the preview box is keyboard focusable`).toBe('0');
        if (width === 390) {
            expect.soft(metrics.layout, `${viewId} ${width}px a phone shows the statement as a record`).toBe('records');
        }

        const box = page.locator(`${section} .query-result-layout > :is(.query-result-table-wrap, .query-result-records):not([hidden])`);
        await focusByKeyboard(page, box);
        await expect.soft(box, `${viewId} ${width}px preview box receives keyboard focus`).toBeFocused();
        const outlineStyle = await box.evaluate(element => getComputedStyle(element).outlineStyle);
        expect.soft(outlineStyle, `${viewId} ${width}px keyboard focus remains visible`).not.toBe('none');
        if (evidenceDirectory) {
            await page.screenshot({ path: path.join(evidenceDirectory, `${viewId}-${width}.png`), fullPage: true });
        }
    }
});

// A table wider than its box (its columns cannot shrink below their readable widths) scrolls sideways inside the box;
// the arrow keys scroll the focused box in every browser, WebKit included.
test('a preview table wider than its box scrolls with the arrow keys', async ({ page }) => {
    await page.setViewportSize({ width: 1600, height: 820 });
    for (const viewId of ['export', 'remove']) {
        const section = await openPreview(page, viewId, false);
        const wrap = page.locator(`${section} .query-result-table-wrap`);
        await expect(page.locator(`${section} .query-result-layout`)).toHaveAttribute('data-effective-layout', 'table');
        await wrap.evaluate(element => {
            const table = element.querySelector('table.data');
            table.style.minWidth = table.style.width = (element.clientWidth * 2) + 'px';
        });
        await expect.poll(() => wrap.evaluate(element => element.scrollWidth > element.clientWidth + 1)).toBe(true);
        await focusByKeyboard(page, wrap);
        await expect(wrap, `${viewId} preview table box receives keyboard focus`).toBeFocused();
        await wrap.evaluate(element => { element.scrollLeft = 0; });
        await page.keyboard.press('ArrowRight');
        await expect.poll(() => wrap.evaluate(element => element.scrollLeft),
            { message: `${viewId} ArrowRight scrolls the focused preview` }).toBeGreaterThan(0);
        const right = await wrap.evaluate(element => element.scrollLeft);
        await page.keyboard.press('ArrowLeft');
        await expect.poll(() => wrap.evaluate(element => element.scrollLeft),
            { message: `${viewId} ArrowLeft scrolls back` }).toBeLessThan(right);
        expect(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth),
            `${viewId} the page itself does not scroll sideways`).toBeLessThanOrEqual(1);
    }
});

test('short four-column previews do not force horizontal scrolling', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 820 });

    for (const viewId of ['export', 'remove']) {
        const section = await openPreview(page, viewId, true);
        const metrics = await page.locator(`${section} .query-result-layout`).evaluate(layout => {
            // The visible box: the table, or the records where four readable columns do not fit the card.
            const scrollport = layout.querySelector(':scope > :is(.query-result-table-wrap, .query-result-records):not([hidden])');
            return {
                layout: layout.getAttribute('data-effective-layout'),
                headerCount: layout.querySelectorAll(':scope > .query-result-table-wrap thead th').length,
                clientWidth: scrollport.clientWidth,
                scrollWidth: scrollport.scrollWidth
            };
        });
        console.log(`PREVIEW_SHORT ${viewId} ${JSON.stringify(metrics)}`);
        expect(metrics.headerCount, `${viewId} short preview keeps four statement columns`).toBe(4);
        expect(metrics.scrollWidth, `${viewId} short preview does not force horizontal scrolling`)
            .toBeLessThanOrEqual(metrics.clientWidth + 1);
    }
});
